switch (order.status) {
  case 'CART':
  case 'PAYMENT_FAILED':
    // 課金されていないことが確定している状態だけ
    order.status = 'CANCELLED';
    break;
  case 'PAID': { /* 変更なし */ }
  default:
    // PENDING_PAYMENT は課金の有無が分からない。照合バッチの決着を待つ
    throw new InvalidOrderStateError(order, 'cancelled');
}

const raw = env.CANCELLATION_FEE_PERCENT;
const feePercent = raw === undefined || raw === '' ? 10 : Number(raw);
if (!Number.isInteger(feePercent) || feePercent < 0 || feePercent > 100) {
  throw new Error(`invalid CANCELLATION_FEE_PERCENT: ${raw}`);
}
